  $seed = $summary.bundledCatalogSeed
  if ($seed.status -notin @("applied", "already_applied") -or $seed.source_id -ne "wikidata-vag-model-taxonomy" -or $seed.models -ne 521 -or $seed.manufacturers -ne 6 -or $seed.verified_models -ne 0 -or $seed.exact_fitments -ne 0 -or $seed.engine_codes -ne 0 -or $seed.transmission_codes -ne 0) { throw "Bundled Wikidata core seed did not remain a candidate-only identity import." }
  $wikidataPackRoot = Join-Path $PSScriptRoot "..\data\research\wikidata-vag-model-taxonomy-cc0"
  $wikidataManifestPath = Join-Path $wikidataPackRoot "manifest.json"
  $wikidataLicensePath = Join-Path $wikidataPackRoot "LICENSE-NOTICE.txt"
  $wikidataSnapshotPath = Join-Path $wikidataPackRoot "snapshot.json"
  $wikidataDatabasePath = Join-Path $wikidataPackRoot "wikidata-vag-taxonomy.sqlite"
  foreach ($file in @($wikidataManifestPath, $wikidataLicensePath, $wikidataSnapshotPath, $wikidataDatabasePath)) { if (-not (Test-Path -LiteralPath $file -PathType Leaf)) { throw "Wikidata CC0 candidate pack file is missing: $file" } }
  $wikidataManifestHash = (Get-FileHash -LiteralPath $wikidataManifestPath -Algorithm SHA256).Hash.ToLowerInvariant()
  $wikidataLicenseHash = (Get-FileHash -LiteralPath $wikidataLicensePath -Algorithm SHA256).Hash.ToLowerInvariant()
  $wikidataSnapshotHash = (Get-FileHash -LiteralPath $wikidataSnapshotPath -Algorithm SHA256).Hash.ToLowerInvariant()
  $wikidataDatabaseHash = (Get-FileHash -LiteralPath $wikidataDatabasePath -Algorithm SHA256).Hash.ToLowerInvariant()
  $wikidataManifest = Get-Content -LiteralPath $wikidataManifestPath -Raw | ConvertFrom-Json
  if ($wikidataManifest.data_license -ne "CC0-1.0" -or $wikidataManifest.rights_status -ne "approved_by_published_license" -or $wikidataManifest.source_revision -ne "wikidata-snapshot-630dbed1af15" -or $wikidataManifest.counts.model_entities -ne 521 -or $wikidataManifest.counts.manufacturers -ne 6 -or $wikidataManifest.counts.source_bindings -ne 530 -or $wikidataManifest.scope.market_scope -ne "UNKNOWN" -or $wikidataManifest.scope.applicability_precision -ne "candidate_identity_only" -or $wikidataManifest.scope.exact_vehicle_fitment -ne $false -or $wikidataManifest.scope.generation_verified -ne $false -or $wikidataManifest.scope.engine_code_fitment -ne $false -or $wikidataManifest.scope.transmission_code_fitment -ne $false) { throw "Wikidata source manifest crossed its CC0 candidate-only scope." }
  if ($wikidataManifest.source_snapshot_sha256 -ne $wikidataSnapshotHash -or $wikidataManifest.database_sha256 -ne $wikidataDatabaseHash -or $wikidataManifest.pack_files.'LICENSE-NOTICE.txt'.sha256 -ne $wikidataLicenseHash) { throw "Wikidata source snapshot, SQLite or license notice hash mismatch." }
  $wikidataSource = @($summary.sources | Where-Object { $_.source_id -eq "wikidata-vag-model-taxonomy" }) | Select-Object -First 1
  if (-not $wikidataSource -or $wikidataSource.status -ne "approved" -or $wikidataSource.rights_status -ne "approved_by_published_license" -or $wikidataSource.license_id -ne "CC0-1.0" -or $wikidataSource.market_scope -ne "UNKNOWN" -or $wikidataSource.record_count -ne 527 -or $wikidataSource.source_snapshot_sha256 -ne $wikidataSnapshotHash -or $wikidataSource.license_sha256 -ne $wikidataLicenseHash -or $wikidataSource.rights_evidence_sha256 -ne $wikidataManifestHash) { throw "Local SQLite source registry does not preserve Wikidata license, rights evidence, snapshot and candidate-only status." }
  foreach ($field in @("commercial_use_allowed", "display_allowed", "offline_cache_allowed", "bulk_reuse_allowed", "redistribution_allowed")) { if ($wikidataSource.$field -ne 1) { throw "Wikidata CC0 rights flag is missing: $field" } }
  if ($wikidataSource.share_alike_required -ne 0 -or $wikidataSource.attribution_required -ne 0) { throw "Wikidata CC0 attribution/share-alike flags are inconsistent." }
  $wikidataModels = @($summary.reviewQueue | Where-Object { $_.source_id -eq "wikidata-vag-model-taxonomy" -and $_.entity_type -eq "vehicle_model" -and $_.review_status -eq "candidate" -and $_.market_scope -eq "UNKNOWN" -and $_.applicability_precision -eq "vehicle_model_candidate" })
  $wikidataBrands = @($summary.reviewQueue | Where-Object { $_.source_id -eq "wikidata-vag-model-taxonomy" -and $_.entity_type -eq "brand" -and $_.review_status -eq "candidate" -and $_.market_scope -eq "UNKNOWN" -and $_.applicability_precision -eq "manufacturer_make_candidate" })
  if ($wikidataModels.Count -ne 521 -or $wikidataBrands.Count -ne 6 -or @($summary.reviewQueue | Where-Object { $_.source_id -eq "wikidata-vag-model-taxonomy" -and $_.review_status -ne "candidate" }).Count -ne 0 -or @($summary.moduleCoverage).Count -ne 0) { throw "Wikidata candidate queue or technical-coverage guard failed." }
  $wikidataBatch = @($summary.importBatches | Where-Object { $_.package_id -eq "wikidata-vag-model-taxonomy-cc0-630dbed1af15" }) | Select-Object -First 1
  if (-not $wikidataBatch -or $wikidataBatch.status -ne "applied" -or $wikidataBatch.records_inserted -ne 527 -or $wikidataBatch.package_sha256 -ne "52c4b195d8200594aca1cec2de93f64f8fbe94a746dea0406715da7348e057d2" -or $seed.packageSha256 -ne $wikidataBatch.package_sha256) { throw "Wikidata candidate package import batch is missing or not transactionally applied." }
  Write-Host "Wikidata CC0 model identity seed passed: 6 manufacturer candidates + 521 model candidates; 0 verified models, generations, engine/gearbox codes or technical records."
